mapper.select:
SELECT ${sqlMap.column.toSql()}
FROM ${sqlMap.table.toSql()}

    ${sqlMap.where.toSql()}


        AND (${sqlMap.where.sqlSegment})


        AND a.employee_id = #{employeeId}


        AND a.employee_name LIKE concat('%', #{employeeName}, '%')


        AND a.department LIKE concat('%', #{department}, '%')


        AND a.work_process LIKE concat('%', #{workProcess}, '%')


        AND a.team LIKE concat('%', #{team}, '%')


        AND a.job_type LIKE concat('%', #{jobType}, '%')


        AND a.work_shift LIKE concat('%', #{workShift}, '%')


        AND a.month = #{month}


ORDER BY ${sqlMap.order.toSql()}

SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.department AS "department", a.work_process AS "workProcess", a.team AS "team", a.job_type AS "jobType", a.work_shift AS "workShift", a.month AS "month", a.scheduled_days AS "scheduledDays", a.actual_days AS "actualDays", a.actual_attendance_days AS "actualAttendanceDays", a.attendance_rate AS "attendanceRate", a.monthly_attendance_rate AS "monthlyAttendanceRate", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.attendance_achievement_rate AS "attendanceAchievementRate", a.idle_hours AS "idleHours", a.efficiency AS "efficiency", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks" FROM swm_attendance_summary a
a.month = #{month}
ORDER BY a.create_date DESC

SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.department AS "department", a.work_process AS "workProcess", a.team AS "team", a.job_type AS "jobType", a.work_shift AS "workShift", a.month AS "month", a.scheduled_days AS "scheduledDays", a.actual_days AS "actualDays", a.actual_attendance_days AS "actualAttendanceDays", a.attendance_rate AS "attendanceRate", a.monthly_attendance_rate AS "monthlyAttendanceRate", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.attendance_achievement_rate AS "attendanceAchievementRate", a.idle_hours AS "idleHours", a.efficiency AS "efficiency", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks" FROM swm_attendance_summary a
a.department = #{param1} AND a.month = #{param2}
ORDER BY a.employee_name ASC

SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.department AS "department", a.work_process AS "workProcess", a.team AS "team", a.job_type AS "jobType", a.work_shift AS "workShift", a.month AS "month", a.scheduled_days AS "scheduledDays", a.actual_days AS "actualDays", a.actual_attendance_days AS "actualAttendanceDays", a.attendance_rate AS "attendanceRate", a.monthly_attendance_rate AS "monthlyAttendanceRate", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.attendance_achievement_rate AS "attendanceAchievementRate", a.idle_hours AS "idleHours", a.efficiency AS "efficiency", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks" FROM swm_attendance_summary a
AND a.employee_id = #{employeeId}
AND a.employee_name = #{employeeName}
AND a.month = #{month}
AND a.department = #{department}
LIMIT 1
